bookInfoRule.init:
@js:
var util = objParse(String(java.get("util")))

function objParse(obj) {
    return JSON.parse(obj, (n, v) => {
        if (typeof v == "string" && v.match("()")) {
            return eval(`(${v})`)
        }
        return v;
    })
}

(function (res) {
    // 获取网址id，请求并解析数据
    let isHtml = result.startsWith("<!DOCTYPE html>")
    if (isHtml) {
        var novelId = 0
        let isSeries = baseUrl.match(new RegExp("pixiv.net/(ajax/|)novel/series"))
        if (isSeries) {
            let seriesId = baseUrl.match(new RegExp("\\d+"))[0]
            java.log(`系列ID：${seriesId}`)
            // 获取系列第一篇小说的 id
            let url = util.urlSeriesNovels(seriesId, 30, 0)
            res = util.cacheGetAndSet(url, () => {
                return JSON.parse(java.ajax(url))
            })
            novelId = res.body.thumbnails.novel[0].id
            java.log(`首篇小说ID：${novelId}`)
            res = util.getAjaxJson(util.urlNovelDetailed(novelId)).body
            // java.log(JSON.stringify(res))
        } else {
            let isNovel = baseUrl.match(new RegExp("pixiv.net/(ajax/|)novel"))
            if (isNovel) {
                novelId = baseUrl.match(new RegExp("\\d+"))[0]
                java.log(`匹配小说ID：${novelId}`)
                res = util.getAjaxJson(util.urlNovelDetailed(novelId)).body
                // java.log(JSON.stringify(res))
            } else {
                return []
            }
        }
    } else {
        // 从搜索直接获取 json
        res = JSON.parse(result).body
        if (res.total === 0) {
            return []
        }
    }


    // java.log(JSON.stringify(res))
    let info = {}
    info.noveId = res.id
    info.title = res.title
    info.userName = res.userName
    // info.tags = res.tags 　// complex array 不好取数据
    // info.textCount = res.textCount  // 无数据
    info.tags = res.userNovels[`${info.noveId}`].tags
    // info.textCount = res.userNovels[`${info.noveId}`].textCount
    // info.readingTime = `${res.userNovels[`${info.noveId}`].readingTime / 60} 分钟`
    info.latestChapter = ""
    info.description = res.description
    info.coverUrl = res.coverUrl
    info.catalogUrl = util.urlNovelDetailed(info.noveId)

    if (res.seriesNavData === undefined || res.seriesNavData === null) {
        info.title = info.latestChapter = res.title
        info.userName = res.userName
        // info.tags = res.userNovels[`${info.noveId}`].tags
        info.tags.unshift('单本')
        info.textCount = res.userNovels[`${info.noveId}`].textCount
        info.latestChapter = res.title
        info.description = res.description
        info.coverUrl = res.coverUrl
        info.catalog = util.urlNovelDetailed(info.noveId)
        info.createDate = res.createDate
        info.updateDate = res.uploadDate

    } else {  // 系列小说
        info.seriesId = res.seriesNavData.seriesId
        info.title = res.seriesNavData.title
        java.log(`${info.seriesId}，${info.title}`)
        res2 = JSON.parse(java.ajax(util.urlSeries(res.seriesNavData.seriesId))).body
        // java.log(JSON.stringify(res2))
        // info.title = res2.title
        // info.userName = res2.userName
        info.tags.push.apply(res2.tags)   //合并当前章节 tags
        info.tags.unshift('长篇')
        info.textCount = res2.publishedTotalCharacterCount
        info.readingTime = `${res2.publishedReadingTime / 60} 分钟`
        info.latestChapter = ""
        info.description = `${res2.caption}\n当前章节简介：\n${info.description}`
        // info.coverUrl = res2.firstEpisode.url   // 第一章封面
        info.coverUrl = res2.cover.urls["480mw"] // 240mw, 480mw, 1200x1200, 128x128, original
        info.catalog = util.urlSeries(info.seriesId)
        info.createDate = res2.createDate
        info.updateDate = res2.updateDate
        info.totalChapterNum = res2.displaySeriesContentCount  //章节总数
        // info.language = res2.language
        // info.publishedContentCount = res2.publishedTotalCharacterCount
        // info.displaySeriesContentCount =
        // info.total = res2.total
        // info.firstNovelId = res2.firstNovelId
        // info.latestNovelId = res2.latestNovelId
    }
    info.tags = info.tags.join(",")
    const time = util.dateFormat(info.updateDate)
    info.description  = `${info.description}\n更新时间:${time}`
    //info.description = `\n书名：${info.title}\n作者：${info.userName}\n标签：${info.tags}\n更新：${time}\n简介：${info.description}`
    return info
})();

contentRule.content:
@js:
var util = objParse(String(java.get("util")))

function objParse(obj) {
    return JSON.parse(obj, (n, v) => {
        if (typeof v == "string" && v.match("()")) {
            return eval(`(${v})`)
        }
        return v;
    })
}

(() => {
    let res = JSON.parse(result).body
    let content = res.content
    // 在正文内部添加小说描述
    if (res.seriesNavData !== undefined && res.seriesNavData !== null && res.description !== "") {
        content = res.description + "\n" + "——————————\n".repeat(2) + content
    }

    // 获取 [uploadedimage:] 的图片链接
    let hasEmbeddedImages = res.textEmbeddedImages !== undefined && res.textEmbeddedImages !== null
    if (hasEmbeddedImages) {
        Object.keys(res.textEmbeddedImages).forEach((key) => {
            content = content.replace(`[uploadedimage:${key}]`, `<img src="${res.textEmbeddedImages[key].urls.original}">`)
        })
    }

    // 获取 [pixivimage:] 的图片链接 [pixivimage:1234] [pixivimage:1234-1]
    let matched = content.match(RegExp(/\[pixivimage:(\d+)-?(\d+)]/gm))
    if (matched) {
        for (let i in matched) {
            let illustId, order
            let matched2 = matched[i].match(RegExp("(\\d+)-?(\\d+)"))
            let temp = matched2[0].split("-")
            illustId = temp[0]
            if (temp.length === 2){
                order = temp[1]
            }
            content = content.replace(`${matched[i]}`, `<img src="${util.urlIllustOriginal(illustId, order)}">`)
        }
    }

    // 替换 Pixiv 分页标记符号 [newpage]
    matched = content.match(RegExp(/[ 　]*\[newpage][ 　]*/gm))
    if (matched) {
        for (let i in matched){
            java.log(matched[i])
            content = content.replace(`${matched[i]}`, `${"<p>​<p/>".repeat(3)}`)
        }
    }

    // 替换 Pixiv 章节标记符号 [chapter:]
    matched = content.match(RegExp(/\[chapter:(.*?)]/gm))
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[chapter:(.*?)]/m)
            let chapter = matched2[1].trim()
            content = content.replace(`${matched[i]}`, `${chapter}<p>​<p/>`)
        }
    }

    // 替换 Pixiv 跳转页面标记符号 [[jump:]]
    matched = content.match(RegExp(/\[jump:(\d+)]/gm))
    if (matched) {
        for (let i in matched) {
            let page = matched[i].match(/\d+/)
            content = content.replace(`${matched[i]}`, `\n\n跳转至第${page}节`)
        }
    }

    // 替换 Pixiv 链接标记符号 [[jumpuri: > ]]
    matched = content.match(RegExp(/\[\[jumpuri:(.*?)>(.*?)]]/gm))
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[\[jumpuri:(.*?)>(.*?)]]/m)
            let matchedText = matched2[0]
            let urlName = matched2[1].trim()
            let urlLink = matched2[2].trim()
            // 阅读不支持超链接
            //content = content.replace(`${matchedText}`, `<a href=${urlLink}>${urlName}</a>`)
            if (urlLink === urlName) {
                content = content.replace(`${matchedText}`, `${urlName}`)
            } else {
                content = content.replace(`${matchedText}`, `${urlName}: ${urlLink}`)
            }
        }
    }

    // 替换 Pixiv 注音标记符号 [[rb: > ]]
    matched = content.match(RegExp(/\[\[rb:(.*?)>(.*?)]]/gm))
    if (matched) {
        for (let i in matched) {
            let matched2 = matched[i].match(/\[\[rb:(.*?)>(.*?)]]/m)
            let matchedText = matched2[0]
            let kanji = matched2[1].trim()
            let kana = matched2[2].trim()
            // kana为中文，则替换回《书名号》
            var reg = new RegExp("[\\u4E00-\\u9FFF]+","g");
            if (reg.test(kana)) {
                content = content.replace(`${matchedText}`, `${kanji}《${kana}》`)
            } else{
                // 阅读不支持 <ruby> <rt> 注音
                // content = content.replace(`${matchedText}`, `<ruby>${kanji}<rt>${kana}</rt></ruby>`)
                content = content.replace(`${matchedText}`, `${kanji}（${kana}）`)
            }
        }
    }

    return content
})()

exploreRule.bookList:
@js:
var util = objParse(String(java.get("util")))

function objParse(obj) {
    return JSON.parse(obj, (n, v) => {
        if (typeof v == "string" && v.match("()")) {
            return eval(`(${v})`)
        }
        return v;
    })
}


// 存储seriesID 有BUG无法处理翻页
var seriesSet = new Set();
// 将多个长篇小说解析为一本书
function combineNovels(novels) {
    return novels.filter(novel => {
        //单本直接解析为一本书
        if (novel.seriesId === undefined || novel.seriesId === null) {
            return true
        }

        //集合中没有该系列解析为一本书
        if (!seriesSet.has(novel.seriesId)) {
            seriesSet.add(novel.seriesId)
            return true
        }

        return false
    })
}

function handNovels(novels) {
    novels.forEach(novel => {
        if (novel.tags === undefined || novel.tags === null) {
            novel.tags = []
        }

        if (novel.seriesId === undefined || novel.seriesId === null) {
            novel.tags.unshift("单本")
        } else {
            let userAllWorks = util.getAjaxJson(util.urlUserAllWorks(novel.userId)).body
            for (let series of userAllWorks.novelSeries) {
                if (series.id === novel.seriesId) {
                    // let series = util.getAjaxJson(util.urlSeries(novel.seriesId)).body
                    novel.textCount = series.publishedTotalCharacterCount
                    novel.url = series.cover.urls["480mw"]
                    novel.title = series.title
                    novel.tags = series.tags
                    novel.description = series.caption

                    try{
                        // 发送请求获取第一章 获取标签与简介
                        if (novel.tags.length === 0 || novel.description === "") {
                            let firstNovel = util.getAjaxJson(util.urlNovelDetailed(series.firstNovelId)).body
                            if (novel.tags.length === 0) {
                                novel.tags = firstNovel.tags.tags.map(item => item.tag)
                            }

                            if (novel.description === "") {
                                novel.description = firstNovel.description
                            }
                        }
                        novel.tags.unshift("长篇")
                        break
                    } catch (e) {
                        java.log(e)
                    }
                }
            }
        }
    })
    return novels
}

function handlerFactory() {
    let cookie = String(java.getCookie("https://www.pixiv.net/", null))
    if (cookie === null || cookie === undefined || cookie === "") {
        return handlerNoLogin()
    }
    if (baseUrl.indexOf("/bookmark") !== -1) {
        return handlerBookMarks()
    }

    if (baseUrl.indexOf("/top") !== -1) {
        return handlerRecommend()
    }

    if (baseUrl.indexOf("/following") !== -1) {
        return handlerFollowing()
    }

    if (baseUrl.indexOf("/follow_latest") !== -1) {
        return handlerFollowLatest()
    }

    if (baseUrl.indexOf("/watch_list") !== -1) {
        return handlerWatchList()
    }
}

function handlerFollowing() {
    return () => {
        let novelList = []
        JSON.parse(result).body.users
            .filter(user => user.novels.length > 0)
            .map(user => user.novels)
            .forEach(novels => {
                return novels.forEach(novel => {
                    novelList.push(novel)
                })
            })
        return util.formatNovels(handNovels(novelList))
    }
}

// 推荐小说
function handlerRecommend() {
    return () => {
        let res = JSON.parse(result)
        const recommend = res.body.page.recommend
        const novels = res.body.thumbnails.novel
        let nidSet = new Set(recommend.ids)
        // java.log(nidSet.size)
        let list = novels.filter(novel => nidSet.has(String(novel.id)))
        // java.log(`过滤结果:${JSON.stringify(list)}`)
        return util.formatNovels(handNovels(combineNovels(list)))
    }
}

function handlerNoLogin() {
    return () => {
        java.longToast("此功能需要在书源登录后才能使用")
        return []
    }
}

// 收藏小说
function handlerBookMarks() {
    return () => {
        let resp = JSON.parse(result).body.works
        if (resp === undefined || resp.length === 0) {
            //流程无法本环节中止 只能交给下一流程处理
            return []
        }

        return util.formatNovels(handNovels(resp))
    }
}

//关注作者，近期小说
function handlerFollowLatest() {
    return () => {
        let resp = JSON.parse(result)
        return util.formatNovels(handNovels(combineNovels(resp.body.thumbnails.novel)))
    }
}

// 追更列表
function handlerWatchList(){
    return () => {
        let resp = JSON.parse(result)
        let novels = []
        let seriesList = resp.body.thumbnails.novelSeries
        for (let i in seriesList) {
            let novelId = seriesList[i].latestEpisodeId  // 使用最后一篇小说，重新请求并合并小说
            novels.push(util.getAjaxJson(util.urlNovelDetailed(novelId)).body.userNovels[`${novelId}`])
        }
        return util.formatNovels(handNovels(combineNovels(novels)))
    }
}

(() => {
    return handlerFactory()()
})()

